/// <summary>
/// This class handles the dialog for attribute group change on Item Group in Rebate module
/// </summary>
internal class METTAMRebateItemGroupAttributeChangeDialog
{
    protected Dialog        dialog;
    protected DialogField   dlguseItemAttributes, dlgProductPriceAttributeGroup;

    private boolean useItemAttributes;
    private GUPPricingAttributeGroupName productPriceAttributeGroup;

}

Method.Source:
    /// <summary>
    /// Entry point method of the operation
    /// </summary>
    /// <param name = "_args">Args</param>
    public static void main(Args _args)
    {
        //Check if the Args.Record() has the same TableID as the Table Buffer(TAMRebateGroup).
        if  (_args.record().TableId == tableNum(TAMRebateGroup))
        {
            //Assign the args records to table buffer and then pass it to salesLine_ds(FormDataSource)
            TAMRebateGroup rebateGroup  = _args.record();
 
            //Call Method which will be used to create the Dialog
            METTAMRebateItemGroupAttributeChangeDialog dialogRebateItemGroupAttributeChangeDialog = new METTAMRebateItemGroupAttributeChangeDialog();

            dialogRebateItemGroupAttributeChangeDialog.updateRebateGroupAttributeDetails(rebateGroup);

            FormDataSource TAMRebateGroup_ds   = FormDataUtil::getFormDataSource(rebateGroup);
            TAMRebateGroup_ds.executeQuery();
        }
    }

/// <summary>
/// Construct and return the class object
/// </summary>
/// <returns>class object</returns>
public static METTAMRebateItemGroupAttributeChangeDialog construct()
{
    return new METTAMRebateItemGroupAttributeChangeDialog();
}

/// <summary>
/// Protected constructor method
/// </summary>
protected void new()
{
}

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <param name = "_rebateGroup">table record used to set initial values</param>
    /// <returns>The dialog</returns>
    protected Dialog dialog(TAMRebateGroup _rebateGroup)
    {
        //Create a Dialog with title
        dialog = new Dialog("@MET:ChangePriceAttributes");

        dlguseItemAttributes    = dialog.addField(ExtendedTypeStr(NoYesId),"@MET:UseItemAttribute");
        dlguseItemAttributes.value(_rebateGroup.METuseItemAttributes);
        //Override modified method for dlguseItemAttributes
        dlguseItemAttributes.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METTAMRebateItemGroupAttributeChangeDialog, dialogUseItemAttribute_modified), this);

        dlgProductPriceAttributeGroup = dialog.addField(extendedTypeStr(GUPPricingAttributeGroupName));
        dlgProductPriceAttributeGroup.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METTAMRebateItemGroupAttributeChangeDialog, lookupProductPriceAttribute), this);
        if(_rebateGroup.METuseItemAttributes)
        {
            dlgProductPriceAttributeGroup.value(strFmt("@MET:P1",_rebateGroup.METGUPProductPricingAttributeGroup));
        }
        else
        {
            dlgProductPriceAttributeGroup.enabled(false);
        }
        

        //Create a "Label" do Dialog
        dialog.addText("@MET:DoYouWishToProceed");

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// disable controls on Dialog form if record need to be deleted
    /// </summary>
    /// <param name = "_dlguseItemAttributes">use item attribute dialog control</param>
    /// <returns>alwyas true</returns>
    private boolean dialogUseItemAttribute_modified(FormCheckBoxControl _dlguseItemAttributes)
    {
        if(_dlguseItemAttributes)
        {
            if (dlguseItemAttributes.value() == true)
            {
                dlgProductPriceAttributeGroup.enabled(true);
            }
            else
            {
                dlgProductPriceAttributeGroup.enabled(false);
                dlgProductPriceAttributeGroup.value('');
            }
        }

        return true;
    }

    /// <summary>
    /// product pricing attribute group lookup
    /// </summary>
    /// <param name = "_formControl">attribute group field control</param>
    private void lookupProductPriceAttribute(FormControl _formControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbdsPricingAttributeGroup;
        SysTableLookup          sysTableLookup;

        if (_formControl != null)
        {
            // Create an instance of SysTableLookup with
            // the current calling form control.

            sysTableLookup = SysTableLookup::newParameters(tablenum(GUPPricingAttributeGroup), _formControl);
            sysTableLookup.addLookupfield(fieldnum(GUPPricingAttributeGroup, Name), true);
            sysTableLookup.addLookupfield(fieldnum(GUPPricingAttributeGroup, Description),false);
            
            qbdsPricingAttributeGroup = query.addDataSource(tableNum(GUPPricingAttributeGroup));
            qbdsPricingAttributeGroup.addSortField(fieldnum(GUPPricingAttributeGroup, Name),SortOrder::Ascending);

            QueryBuildRange  qbrGroupType = qbdsPricingAttributeGroup.addRange(fieldNum(GUPPricingAttributeGroup,GroupType));
            qbrGroupType.value(SysQuery::value(GUPPricingAttributeGroupType::Product));
            sysTableLookup.parmUseLookupValue(false);

            sysTableLookup.parmQuery(query);

            // Perform the lookup.
            sysTableLookup.performFormLookup();
        }
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    protected boolean getFromDialog()
    {
        boolean ret = true;

        useItemAttributes           = dlguseItemAttributes.value();
        productPriceAttributeGroup  = dlgProductPriceAttributeGroup.value();
        
        //do any validation here
        if(useItemAttributes == NoYes::Yes && productPriceAttributeGroup == '')
        {
            ret = checkFailed("@MET:ProductAttributeGroupNameMandatory");
        }
        else if (useItemAttributes == NoYes::Yes)
        {
            GUPPricingAttributeGroup pricingGroup;
            select firstonly * from pricingGroup
                where   pricingGroup.Name       == productPriceAttributeGroup && 
                        pricingGroup.GroupType  == GUPPricingAttributeGroupType::Product;

            if(!pricingGroup.RecId)
            {
                ret = checkFailed(strFmt("@MET:InvalidProductAttributeGroupName",pricingGroup.Name));
            }

        }

        return ret;
    }

    /// <summary>
    /// Updates the excise register entries incoming from Args.
    /// </summary>
    /// <param name = "_rebateGroup">Table buffer of <c>TAMRebateGroup</c></param>
    private void updateRebateGroupAttributeDetails(TAMRebateGroup _rebateGroup)
    {
        #OCCRetryCount

        TAMRebateGroup rebateGroup = _rebateGroup;
        dialog = this.dialog(rebateGroup);

        //The code will only be executed if the user click on Yes
        if (dialog.run())
        {
            if(this.getFromDialog())
            {
                if(rebateGroup.METGUPProductPricingAttributeGroup != productPriceAttributeGroup ||
                       rebateGroup.METuseItemAttributes != useItemAttributes)
                {
                    try
                    {
                        ttsbegin;
                        rebateGroup.selectForUpdate(true);
                        rebateGroup.METGUPProductPricingAttributeGroup  = productPriceAttributeGroup;
                        rebateGroup.METuseItemAttributes                = useItemAttributes;
                        rebateGroup.update();
                        ttscommit;
                    }
                    catch (Exception::Deadlock)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            error (strFmt("@MET:RebateGroupAttributeAssignError", rebateGroup.RebateGroupId));
                            error("@Subledger:DeadlockErrorThrown");
                        }
                        else
                        {
                            retry;
                        }
                    }
                    catch (Exception::UpdateConflict)
                    {
                        if (appl.ttsLevel() == 0)
                        {
                            if (xSession::currentRetryCount() >= #RetryNum)
                            {
                                error (strFmt("@MET:RebateGroupAttributeAssignError", rebateGroup.RebateGroupId));
                                error("@Subledger:UpdateConflictErrorThrown");
                            }
                            else
                            {
                                retry;
                            }
                        }
                        else
                        {
                            error (strFmt("@MET:RebateGroupAttributeAssignError", rebateGroup.RebateGroupId));
                            error("@Subledger:UpdateConflictErrorThrown");
                        }
                    }
                    catch
                    {
                        error (strFmt("@MET:RebateGroupAttributeAssignError", rebateGroup.RebateGroupId));
                    }
                }
            }
        }
    }
